-- CoreProtect fork 25.3.0 SQLite schema, dumped from TFMCDev01 on 2026-10-06 for tests.
CREATE TABLE co_art_map (id INTEGER, art TEXT);
CREATE TABLE co_block (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, type INTEGER, data INTEGER, meta BLOB, blockdata BLOB, action INTEGER, rolled_back INTEGER);
CREATE TABLE co_chat (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, message TEXT);
CREATE TABLE co_command (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, message TEXT);
CREATE TABLE co_container (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, type INTEGER, data INTEGER, amount INTEGER, metadata BLOB, action INTEGER, rolled_back INTEGER);
CREATE TABLE co_entity_container (time INTEGER, user INTEGER, entity_spawn_rowid INTEGER NOT NULL, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, type INTEGER, data INTEGER, amount INTEGER, metadata BLOB, action INTEGER, rolled_back INTEGER);
CREATE TABLE co_entity_interaction (time INTEGER, user INTEGER, entity_spawn_rowid INTEGER NOT NULL, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, type INTEGER, action INTEGER, metadata BLOB, rolled_back INTEGER);
CREATE TABLE co_item (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, type INTEGER, data BLOB, amount INTEGER, action INTEGER, rolled_back INTEGER);
CREATE TABLE co_database_lock (status INTEGER, time INTEGER);
CREATE TABLE co_entity (id INTEGER PRIMARY KEY ASC, time INTEGER, data BLOB);
CREATE TABLE co_entity_spawn (id INTEGER PRIMARY KEY ASC, time INTEGER, block_rowid INTEGER, kill_rowid INTEGER, uuid TEXT UNIQUE, wid INTEGER, current_wid INTEGER, origin_x REAL, origin_y REAL, origin_z REAL, x REAL, y REAL, z REAL, yaw REAL, pitch REAL, data BLOB, removed INTEGER);
CREATE TABLE co_entity_map (id INTEGER, entity TEXT);
CREATE TABLE co_material_map (id INTEGER, material TEXT);
CREATE TABLE co_blockdata_map (id INTEGER, data TEXT);
CREATE TABLE co_session (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, action INTEGER);
CREATE TABLE co_sign (time INTEGER, user INTEGER, wid INTEGER, x INTEGER, y INTEGER, z INTEGER, action INTEGER, color INTEGER, color_secondary INTEGER, data INTEGER, waxed INTEGER, face INTEGER, line_1 TEXT, line_2 TEXT, line_3 TEXT, line_4 TEXT, line_5 TEXT, line_6 TEXT, line_7 TEXT, line_8 TEXT);
CREATE TABLE co_skull (id INTEGER PRIMARY KEY ASC, time INTEGER, owner TEXT, skin TEXT);
CREATE TABLE co_user (id INTEGER PRIMARY KEY ASC, time INTEGER, user TEXT, uuid TEXT);
CREATE TABLE co_username_log (id INTEGER PRIMARY KEY ASC, time INTEGER, uuid TEXT, user TEXT);
CREATE TABLE co_version (time INTEGER, version TEXT);
CREATE TABLE co_world (id INTEGER, world TEXT);
CREATE INDEX art_map_id_index ON co_art_map(id);
CREATE INDEX block_index ON co_block(wid,x,z,time);
CREATE INDEX block_user_index ON co_block(user,time);
CREATE INDEX block_type_index ON co_block(type,time);
CREATE INDEX blockdata_map_id_index ON co_blockdata_map(id);
CREATE INDEX chat_index ON co_chat(time);
CREATE INDEX chat_user_index ON co_chat(user,time);
CREATE INDEX chat_wid_index ON co_chat(wid,x,z,time);
CREATE INDEX command_index ON co_command(time);
CREATE INDEX command_user_index ON co_command(user,time);
CREATE INDEX command_wid_index ON co_command(wid,x,z,time);
CREATE INDEX container_index ON co_container(wid,x,z,time);
CREATE INDEX container_user_index ON co_container(user,time);
CREATE INDEX container_type_index ON co_container(type,time);
CREATE INDEX entity_container_index ON co_entity_container(wid,x,z,time);
CREATE INDEX entity_container_spawn_index ON co_entity_container(entity_spawn_rowid,time);
CREATE INDEX entity_container_user_index ON co_entity_container(user,time);
CREATE INDEX entity_container_type_index ON co_entity_container(type,time);
CREATE INDEX entity_interaction_index ON co_entity_interaction(wid,x,z,time);
CREATE INDEX entity_interaction_spawn_index ON co_entity_interaction(entity_spawn_rowid,time);
CREATE INDEX entity_interaction_user_index ON co_entity_interaction(user,time);
CREATE INDEX entity_interaction_type_index ON co_entity_interaction(type,time);
CREATE INDEX entity_interaction_action_index ON co_entity_interaction(action,time);
CREATE INDEX item_index ON co_item(wid,x,z,time);
CREATE INDEX item_user_index ON co_item(user,time);
CREATE INDEX item_type_index ON co_item(type,time);
CREATE INDEX entity_map_id_index ON co_entity_map(id);
CREATE INDEX entity_spawn_time_index ON co_entity_spawn(time);
CREATE INDEX entity_spawn_wid_index ON co_entity_spawn(wid);
CREATE INDEX entity_spawn_current_location_index ON co_entity_spawn(current_wid,x,z);
CREATE UNIQUE INDEX entity_spawn_kill_rowid_index ON co_entity_spawn(kill_rowid);
CREATE INDEX material_map_id_index ON co_material_map(id);
CREATE INDEX session_index ON co_session(wid,x,z,time);
CREATE INDEX session_action_index ON co_session(action,time);
CREATE INDEX session_user_index ON co_session(user,time);
CREATE INDEX session_time_index ON co_session(time);
CREATE INDEX sign_index ON co_sign(wid,x,z,time);
CREATE INDEX sign_user_index ON co_sign(user,time);
CREATE INDEX sign_time_index ON co_sign(time);
CREATE INDEX user_index ON co_user(user);
CREATE INDEX uuid_index ON co_user(uuid);
CREATE INDEX username_log_uuid_index ON co_username_log(uuid,user);
CREATE INDEX world_id_index ON co_world(id);
CREATE INDEX chat_message_prefix_index ON co_chat(substr(message,1,16) COLLATE NOCASE);
CREATE INDEX command_message_prefix_index ON co_command(substr(message,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_1_prefix_index ON co_sign(substr(line_1,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_2_prefix_index ON co_sign(substr(line_2,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_3_prefix_index ON co_sign(substr(line_3,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_4_prefix_index ON co_sign(substr(line_4,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_5_prefix_index ON co_sign(substr(line_5,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_6_prefix_index ON co_sign(substr(line_6,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_7_prefix_index ON co_sign(substr(line_7,1,16) COLLATE NOCASE);
CREATE INDEX sign_line_8_prefix_index ON co_sign(substr(line_8,1,16) COLLATE NOCASE);
